        val id: String get() = "joke-" + text.hashCode().toUInt().toString(16)
        val repetitionGroup: String get() = id
        val tone: String get() = if (category == "whimsy") "playful" else "light"
        val audience = "general"
        val provenance = "Authored for Run; no attributed speaker"
    }
